    const delegation = [...view.delegations.values()].find((item) => item.slotIndex === slot.index);
    if (!delegation) { await appendWal(rootDir, dispatchCallId, "not_admitted_due_to_call_cancel", { index: slot.index, cancelSeq, settlement: "not_admitted_due_to_call_cancel" }, undefined, deps); continue; }
    if (delegation.state === "returned") {
      const terminal = view.events.filter((event) => event.delegationId === delegation.delegationId && ["delegation_returned", "execution_outcome_captured"].includes(event.type)).at(-1);
      if (!terminal || !validResultRef(terminal.data.resultRef)) throw new Error("returned slot result provenance cannot be proven");
      await appendWal(rootDir, dispatchCallId, "returned_before_call_cancel", { index: slot.index, resultRef: terminal.data.resultRef, returnSeq: terminal.seq, cancelSeq }, undefined, deps); continue;
    }
    if (delegation.state !== "cancelled") {
      if (!hasCancelRequest(view, delegation.delegationId)) await appendWal(rootDir, dispatchCallId, "cancel_requested", { target: delegation.delegationId, scope: "item", actorRef: cancel.data.actorRef, parentSessionId: actor.parentSessionId, activeLineageId: actor.activeLineageId, activeBranchAnchor: actor.activeBranchAnchor, priorState: delegation.state }, delegation.delegationId, deps);
      await reconcileDelegationCancelLocked(rootDir, dispatchCallId, delegation.delegationId, deps);
      view = await loadView(rootDir, dispatchCallId);
    }
    const settled = view.delegations.get(delegation.delegationId);
    if (settled?.state === "cancelled") await appendWal(rootDir, dispatchCallId, "call_cancel_admitted_cancelled", { index: slot.index, delegationId: delegation.delegationId, cancelSeq, settlement: "admitted_cancelled" }, undefined, deps);
